from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string")

    result = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            balance -= 1
            current_group.append(char)

            if balance < 0:
                raise ValueError("Malformed input: too many closing parentheses.")

            if balance == 0:
                result.append("".join(current_group))
                current_group = []
        elif char != ' ':
            raise ValueError(f"Invalid character encountered: '{char}'")

    if balance != 0:
        raise ValueError("Malformed input: unclosed parentheses remaining.")

    return result

from typing import List
import math
def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """ Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    """
    if not isinstance(threshold, (int, float)) or math.isnan(threshold):
        raise ValueError("Threshold must be a valid, non-NaN number")
    if threshold < 0:
        raise ValueError("Threshold must be non-negative")

    clean_nums = []
    for n in numbers:
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            raise TypeError("All elements must be numbers")
        if not math.isfinite(n):
            raise ValueError("NaN and Infinity values are not supported")
        clean_nums.append(float(n))

    if len(clean_nums) < 2:
        return False

    sorted_nums = sorted(clean_nums)
    for a, b in zip(sorted_nums, sorted_nums[1:]):
        if b - a < threshold:
            return True
    return False

from typing import List
def filter_by_substring(strings: List[str], substring: str) -> List[str]:
    """ Filter an input list of strings only for ones that contain given substring
    >>> filter_by_substring([], 'a')
    []
    >>> filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a')
    ['abc', 'bacd', 'array']
    """
    if type(strings) is not list:
        raise TypeError("Input 'strings' must be strictly a list.")
    if type(substring) is not str:
        raise TypeError("Input 'substring' must be strictly a string.")

    for s in strings:
        if type(s) is not str:
            raise TypeError("All elements in 'strings' must be strictly strings.")

    return [s for s in strings if substring in s]

from typing import List
def parse_nested_parens(paren_string: str) -> List[int]:
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string.")

    def get_max_depth(group: str) -> int:
        depth = 0
        max_d = 0
        for char in group:
            if char == '(':
                depth += 1
                if depth > max_d:
                    max_d = depth
            elif char == ')':
                depth -= 1
                if depth < 0:
                    raise ValueError("Unbalanced parentheses: too many closing parentheses.")
            else:
                raise ValueError(f"Invalid character encountered: {char}")

        if depth != 0:
            raise ValueError("Unbalanced parentheses: unclosed parentheses.")

        return max_d

    return [get_max_depth(group) for group in paren_string.split()]

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    if type(a) is not str or type(b) is not str:
        raise TypeError("Inputs must be strictly strings.")
    if len(a) != len(b):
        raise ValueError("Inputs must have the same length.")

    if not set(a).issubset({'0', '1'}) or not set(b).issubset({'0', '1'}):
        raise ValueError("Inputs must only contain '0' and '1'.")

    return "".join("0" if x == y else "1" for x, y in zip(a, b))

from typing import List
from itertools import accumulate
def rolling_max(numbers: List[int]) -> List[int]:
    """ From a given list of integers, generate a list of rolling maximum element found until given moment
    in the sequence.
    >>> rolling_max([1, 2, 3, 2, 3, 4, 2])
    [1, 2, 3, 3, 3, 4, 4]
    """
    if not isinstance(numbers, list):
        raise TypeError("Input 'numbers' must be a list.")

    for x in numbers:
        if type(x) is not int:
            raise TypeError("All elements in 'numbers' must be strictly integers.")

    return list(accumulate(numbers, max))

from typing import List, Tuple
import math
def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    """
    if not isinstance(numbers, list):
        raise TypeError("Input 'numbers' must be a list.")

    for x in numbers:
        if type(x) is not int:
            raise TypeError("All elements in 'numbers' must be strictly integers.")

    return sum(numbers), math.prod(numbers)

from typing import List, Optional
def longest(strings: List[str]) -> Optional[str]:
    """ Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest([])

    >>> longest(['a', 'b', 'c'])
    'a'
    >>> longest(['a', 'bb', 'ccc'])
    'ccc'
    """
    if not isinstance(strings, list):
        raise TypeError("Input 'strings' must be a list.")

    for s in strings:
        if type(s) is not str:
            raise TypeError("All elements in 'strings' must be strictly strings.")

    if not strings:
        return None

    return max(strings, key=len)

def count_distinct_characters(string: str) -> int:
    """ Given a string, find out how many distinct characters (regardless of case) does it consist of
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
    """
    if type(string) is not str:
        raise TypeError("Input 'string' must be strictly a string.")

    return len(set(string.lower()))

def sort_numbers(numbers: str) -> str:
    """ Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sort_numbers('three one five')
    'one three five'
    """
    if type(numbers) is not str:
        raise TypeError("Input 'numbers' must be strictly a string.")
    if len(numbers) > 10**6:
        raise ValueError("Input string is too long, preventing potential DoS.")

    value_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    try:
        return ' '.join(sorted(numbers.split(), key=value_map.__getitem__))
    except KeyError as e:
        raise ValueError(f"Invalid number word found: {e.args[0]}")

